package io.github.miklires.mcodes;import org.junit.jupiter.api.Test;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class CodeDefinitionTest {@Test void rejectsUnsafeIdentifiersAndCommands(){assertThrows(IllegalArgumentException.class,()->new CodeDefinition("bad code",CodeType.PROMO,null,1,1,0,null,null,"",0,List.of(),List.of()));assertThrows(IllegalArgumentException.class,()->new CodeDefinition("safe",CodeType.PROMO,null,1,1,0,null,null,"",0,List.of("say ok\nop me"),List.of()));}@Test void hmacIsStableAndSecretKeyed(){var first=new IdentityHasher("12345678901234567890123456789012");var second=new IdentityHasher("abcdefghijklmnopqrstuvwxyzABCDEF");assertEquals(first.hash("127.0.0.1"),first.hash("127.0.0.1"));assertNotEquals(first.hash("127.0.0.1"),second.hash("127.0.0.1"));}}
